package dev.mesbase.framework.web.service;
import dev.mesbase.common.core.redis.RedisCache;import dev.mesbase.common.core.domain.AjaxResult;import dev.mesbase.system.service.ISysConfigService;import org.springframework.core.env.Environment;import java.util.*;
/** SOURCE_PRODUCT_PORT of CaptchaController/Config; secrets one-use, configuration in YAML. */
@org.springframework.stereotype.Service @org.springframework.boot.autoconfigure.condition.ConditionalOnProperty(name="mes.system.enabled",havingValue="true")
public class CaptchaService {
 private final RedisCache cache;private final ISysConfigService config;private final Environment env;private final dev.mesbase.common.utils.PasswordPolicy passwords;private final com.google.code.kaptcha.impl.DefaultKaptcha producer;
 public CaptchaService(RedisCache cache,ISysConfigService config,Environment env,dev.mesbase.common.utils.PasswordPolicy passwords){this.cache=cache;this.config=config;this.env=env;this.passwords=passwords;var props=new java.util.Properties();props.setProperty("kaptcha.border","yes");props.setProperty("kaptcha.image.width",env.getProperty("ruoyi.captcha.width","160"));props.setProperty("kaptcha.image.height",env.getProperty("ruoyi.captcha.height","60"));props.setProperty("kaptcha.textproducer.font.size",env.getProperty("ruoyi.captcha.font-size","36"));props.setProperty("kaptcha.textproducer.char.length",env.getProperty("ruoyi.captcha.length","4"));props.setProperty("kaptcha.textproducer.font.names","Arial,Courier");if("math".equals(env.getProperty("ruoyi.captcha.type","char")))props.setProperty("kaptcha.textproducer.impl","dev.mesbase.framework.config.KaptchaTextCreator");producer=new com.google.code.kaptcha.impl.DefaultKaptcha();producer.setConfig(new com.google.code.kaptcha.util.Config(props));}
 public boolean enabled(){return env.getProperty("ruoyi.captcha.enabled",Boolean.class,true)&&config.selectCaptchaOnOff();}
 public AjaxResult image()throws java.io.IOException{var result=AjaxResult.success();result.put("captchaOnOff",enabled());result.put("registrationEnabled","true".equals(config.selectConfigByKey("sys.account.registerUser")));result.put("passwordPolicy",passwords.view());if(!enabled())return result;String text=producer.createText(),shown=text,code=text;if(text.contains("@")){shown=text.substring(0,text.lastIndexOf('@'));code=text.substring(text.lastIndexOf('@')+1);}var image=producer.createImage(shown);String id=java.util.UUID.randomUUID().toString();cache.setCacheObject("mes:system:captcha:"+id,code,env.getProperty("ruoyi.captcha.expiration-minutes",Integer.class,2),java.util.concurrent.TimeUnit.MINUTES);var out=new java.io.ByteArrayOutputStream();javax.imageio.ImageIO.write(image,"png",out);result.put("uuid",id);result.put("img",java.util.Base64.getEncoder().encodeToString(out.toByteArray()));return result;}
 public void validate(String uuid,String code){if(!enabled())return;if(uuid==null||!uuid.matches("[a-f0-9-]{36}")||code==null)throw denied();String expected=cache.getAndDelete("mes:system:captcha:"+uuid);if(expected==null||!expected.equalsIgnoreCase(code))throw denied();}
 private RuntimeException denied(){return new dev.mesbase.core.error.FoundationException(dev.mesbase.core.error.ErrorCode.UNAUTHENTICATED);}
}
